import java.util.*;

class Solution {
  public List<List<Integer>> highestRankedKItems(int[][] grid, int[] pricing, int[] start, int k) {
    int m = grid.length, n = grid[0].length;
    boolean[][] seen = new boolean[m][n];
    Queue<int[]> q = new ArrayDeque<>();
    q.add(new int[] {start[0], start[1]});
    seen[start[0]][start[1]] = true;
    List<List<Integer>> ans = new ArrayList<>();
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!q.isEmpty() && ans.size() < k) {
      List<int[]> layer = new ArrayList<>();
      int sz = q.size();
      while (sz-- > 0) {
        int[] p = q.poll();
        if (grid[p[0]][p[1]] >= pricing[0] && grid[p[0]][p[1]] <= pricing[1]) layer.add(p);
        for (int[] d : dirs) {
          int x = p[0] + d[0], y = p[1] + d[1];
          if (x >= 0 && x < m && y >= 0 && y < n && !seen[x][y] && grid[x][y] > 0) {
            seen[x][y] = true;
            q.add(new int[] {x, y});
          }
        }
      }
      layer.sort(
          (a, b) -> {
            if (grid[a[0]][a[1]] != grid[b[0]][b[1]])
              return Integer.compare(grid[a[0]][a[1]], grid[b[0]][b[1]]);
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
          });
      for (int[] p : layer) {
        if (ans.size() == k) break;
        ans.add(Arrays.asList(p[0], p[1]));
      }
    }
    return ans;
  }
}
